  const act = aS/9, inh = iS/9, harm = hS/9;
  const bg = (Math.sin(fx*0.04+fy*0.025+t*0.8) + Math.sin(fx*0.03-fy*0.04+t*1.1))/2 + Math.sin((fx+fy)*0.12+t*2.5)*0.2 + Math.sin((fx-fy)*0.1-t*2)*0.2 + Math.sin(fx*0.08+fy*0.06+t*1.8)*0.15;
