  const cross = act * inh * 0.3 + harm * act * 0.2;
  const reaction = Math.tanh((act - inh*0.7 + bg*0.3 + spiral + cross)*2.2);
  const cell = Math.tanh((Math.sin(fx*0.15)*Math.sin(fy*0.15) + Math.sin((fx+fy)*0.1+t)*0.5)*1.5)*0.3;
